{
  "selections": [
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data", "/situations/3", "/situations/1"],
      "relevance": "내담자가 '저라는 사람이 있었는지 모르겠다', '저한테는 아무도 안 물어본 것 같기도 하고'라고 말한 것은 타인중심성 핵심 믿음이 작동하여 자기 존재 자체가 소거된 상태를 보여줌. 배경 /childhood_data의 '남을 돌볼 때만 가치 있다'는 신념, /situations/3의 '내가 원하는 거 생각해 본 적이 없는 것 같은데', /situations/1의 '왜 아무도 나한테는 힘드냐고 안 물어보지'와 직접 연결됨."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/2", "/situations/3"],
      "relevance": "자기희생 스키마가 작동하여 내담자가 자기 욕구를 완전히 무시해 온 패턴이 '솔직히 모르겠어요'라는 말로 드러남. /situations/2에서 친구 고민을 끝까지 들어주고 자기 이야기는 꺼내지 않은 것, /situations/3에서 배우자에게도 뭘 원하는지 말하지 않은 것이 같은 패턴의 사례임."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "'내 욕구보다 남의 욕구가 먼저'라는 핵심 믿음이 내담자로 하여금 자기에게 '뭘 원하는지' 물어보지 못하게 한 뿌리. /situations/3의 자동사고 '내가 원하는 거...? 그런 걸 생각해 본 적이 없는 것 같은데'가 현재 상담의 '모르겠다는 게 슬프다'와 동일한 내용을 담고 있음."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "'자기 욕구를 주장하면 죄책감을 느끼고, 돌봄을 받는 것보다 주는 역할에만 익숙함'이라는 정의가 내담자가 아이에게 더 조심스럽게 대해준 뒤에도 자기 상태를 묻지 않은 행동과 일치. /childhood_data의 '이기적이다' 핀잔과 '우리 딸이 최고다' 칭찬의 조건부 사랑이 이 정의를 형성함."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "'내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일이다'라는 태도가 내담자로 하여금 자기에게도 물어보지 못하게 함. /situations/1의 자동사고 '이런 생각 하는 것 자체가 못됐어'가 현재 '제가 저한테 물어본 적도 없는 것 같아서 그게 더 이상해요'와 같은 자기 검열 구조를 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0", "/situations/1"],
      "relevance": "'힘들어도 내색하지 않아야 한다'는 규칙이 내담자가 자기 상태를 자각하지 못하게 차단해 온 메커니즘. /situations/0에서 몸살약 먹으며 근무하고 집에 와선 아프다는 말을 안 한 것, /situations/1에서 눈물 나면서도 '피곤해서 그래'라고 한 것이 이 규칙의 작동 사례."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/childhood_data"],
      "relevance": "'다른 사람을 먼저 챙기면 좋은 사람으로 여겨지고 곁에 둘 것'이라는 긍정 가정이 내담자가 자기 욕구를 묻지 않고 타인 돌봄에 몰두해 온 동기를 설명. /childhood_data에서 동생을 돌보거나 집안일을 도우면 '우리 딸이 최고다'라는 칭찬을 받은 경험이 이 가정을 강화함."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "'내 욕구를 주장하면 이기적인 사람으로 여겨져 비난받을 것'이라는 부정 가정이 내담자가 자기 욕구를 인식하고도 표현하지 못하게 함. /situations/3에서 배우자의 질문에 '나는 다 괜찮아'로 얼버무린 것이 이 가정이 작동한 결과이며, 현재 '모르겠어요'라는 반응의 저변에도 이 가정이 있음."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1", "/situations/2"],
      "relevance": "내담자가 '그날 제가 뭘 느꼈는지를 솔직히 생각해본 적이 없는 것 같아요'라고 말한 것은 자기 상태를 숨기는 대처가 장기화되어 자기 감정 자체에 접근하지 못하게 된 결과를 보여줌. /situations/1에서 '피곤해서 그래'로 서운함을 덮고, /situations/2에서 자기 고민을 한마디도 꺼내지 않은 것이 같은 패턴."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 아이에게 소리를 지른 뒤 '평소보다 더 조심스럽게 대해줬다'는 것은 폭발→죄책감→과잉 헌신으로 만회하는 대처 순환의 직접적 사례. /situations/1에서 가족 모임 후 눈물이 났지만 배우자에게 '피곤해서'로 넘긴 것과 같은 죄책감 기반 자기 억압 구조가 반복됨."
    }
  ]
}

